#!/bin/bash
# Junta a voz (ElevenLabs) ao vídeo já montado: o vídeo não é recodificado.
# Uso: juntar_voz.sh <video-sem-voz.mp4> <pasta dos mp3> <saida.mp4> [ffmpeg]
set -e
V="$1"; A="$2"; O="$3"; FF="${4:-ffmpeg}"
"$FF" -y -v error -i "$V" -i "$A/00_intro.mp3" -i "$A/01_conta.mp3" -i "$A/02_contactos.mp3" -i "$A/03_cliente_ficha.mp3" -i "$A/04_cliente_criado.mp3" -i "$A/05_obras.mp3" -i "$A/06_obra_ficha.mp3" -i "$A/07_obra_criada.mp3" -i "$A/08_cinco_obras.mp3" -i "$A/09_obra_porto.mp3" -i "$A/10_marcos.mp3" -i "$A/11_orcamento.mp3" -i "$A/12_equipa.mp3" -i "$A/13_perfis.mp3" -i "$A/14_planos.mp3" -i "$A/15_sub_conforme.mp3" -i "$A/16_sub_reservas.mp3" -i "$A/17_auto_avanco.mp3" -i "$A/18_auto_excesso.mp3" -i "$A/19_planeamento.mp3" -i "$A/20_ata.mp3" -i "$A/21_portal.mp3" -i "$A/22_fim.mp3" -filter_complex "[1:a]adelay=300:all=1[a0];[2:a]adelay=11133:all=1[a1];[3:a]adelay=21700:all=1[a2];[4:a]adelay=29667:all=1[a3];[5:a]adelay=37200:all=1[a4];[6:a]adelay=41033:all=1[a5];[7:a]adelay=47733:all=1[a6];[8:a]adelay=54167:all=1[a7];[9:a]adelay=64033:all=1[a8];[10:a]adelay=69500:all=1[a9];[11:a]adelay=78400:all=1[a10];[12:a]adelay=88133:all=1[a11];[13:a]adelay=98533:all=1[a12];[14:a]adelay=105700:all=1[a13];[15:a]adelay=119033:all=1[a14];[16:a]adelay=132300:all=1[a15];[17:a]adelay=143600:all=1[a16];[18:a]adelay=156733:all=1[a17];[19:a]adelay=171967:all=1[a18];[20:a]adelay=182533:all=1[a19];[21:a]adelay=193700:all=1[a20];[22:a]adelay=204100:all=1[a21];[23:a]adelay=215400:all=1[a22];[a0][a1][a2][a3][a4][a5][a6][a7][a8][a9][a10][a11][a12][a13][a14][a15][a16][a17][a18][a19][a20][a21][a22]amix=inputs=23:normalize=0:dropout_transition=0,apad[a]" -map 0:v -map "[a]" -c:v copy -c:a aac -b:a 160k -ar 44100 -ac 2 -shortest -movflags +faststart "$O.tmp.mp4"
mv "$O.tmp.mp4" "$O"
